	if (text.includes("technic") || text.includes("pin") || text.includes("axle") || text.includes("beam") || text.includes("gear") || text.includes("liftarm")) return "technic";
	if (text.includes("wheel") || text.includes("tire") || text.includes("tyre") || text.includes("rim")) return "wheel";
	if (text.includes("plant") || text.includes("leaf") || text.includes("flower") || text.includes("stem") || text.includes("frog") || text.includes("bamboo") || text.includes("tree")) return "plant";
	if (text.includes("window") || text.includes("windscreen") || text.includes("glass") || text.includes("door")) return "window";
	if (text.includes("arch")) return "arch";
	if (text.includes("wedge") || text.includes("wing")) return "wedge";
	if (text.includes("slope") || text.includes("curved") || text.includes("cheese") || text.includes("roof")) return "slope";
	if (text.includes("hinge") || text.includes("clip") || text.includes("bar") || text.includes("bracket") || text.includes("ball")) return "hinge";
	if (text.includes("panel") || text.includes("wall") || text.includes("fence")) return "panel";
	if (text.includes("round") || text.includes("cylinder") || text.includes("cone") || text.includes("dish") || text.includes("dome")) return "round";
	if (text.includes("tile") || text.includes("jumper")) return "tile";
	if (text.includes("plate")) return "plate";
