		plate: "Platen",
		tile: "Tegels",
		slope: "Schuine stenen",
		round: "Rond & Cilinders",
		technic: "Technic",
		wedge: "Wiggen & Vleugels",
		arch: "Bogen",
		window: "Ramen & Deuren",
		plant: "Planten & Natuur",
		wheel: "Wielen & Banden",
		minifig: "Minifiguren",
		sticker: "Stickers",
		hinge: "Scharnieren & Clips",
		panel: "Panelen",
		other: "Speciaal"
