		[/\btechnic\s+axle\b/i, "Technic Axle"],
		[/\btechnic\s+(beam|liftarm)\b/i, "Technic Beam"],
		[/\btechnic\s+gear\b/i, "Technic Gear"],
		[/\btechnic\s+bush\b/i, "Technic Bush"],
		[/\btechnic\s+connector\b/i, "Technic Connector"],
		[/\btechnic\s+brick\b/i, "Technic Brick"],
		[/\btechnic\s+panel\b/i, "Technic Panel"],
		[/\bminifig.*torso\b/i, "Minifig Torso"],
		[/\bminifig.*(leg|hip)\b/i, "Minifig Benen"],
		[/\bminifig.*head\b/i, "Minifig Hoofd"],
		[/\bminifig.*(hair|helmet|hat|cap)\b/i, "Minifig Haar / Helm"],
		[/\bsticker\b/i, "Sticker"],
		[/\btire|tyre\b/i, "Band (Tire)"],
		[/\bwheel\b/i, "Wiel (Wheel)"],
		[/\bwindscreen\b/i, "Voorruit (Windscreen)"],
		[/\bwindow\b/i, "Raam (Window)"],
		[/\bdoor\b/i, "Deur (Door)"],
		[/\bplant|leaf|leaves|flower\b/i, "Plant / Blad"]
