		ops += 1;
		let bestIdx = -1;
		let bestScore = -1;
		for (let i = 0; i < clusters.length; i++) {
			const s = computeErgonomicSplitScore(clusters[i], false);
			if (s > bestScore + EPS) {
				bestScore = s;
				bestIdx = i;
			}
		}
		if (bestIdx === -1) break;
		seq += 1;
		const halves = splitClusterIntoTwo(clusters[bestIdx], gamma, true, false, weights, `FX_LIM${seq}`);
		if (!halves) break;
